import sympy
from sympy import *

def pre_condition_0(x:sympy.Rational):
	#Eq(x, 1/64)

	pre_cond = Equality(Symbol('x'), Rational(1, 64))

	eval = pre_cond.subs( { 'x':x })

	if eval==True:
		assert eval!=False
		return True
	return False


def pre_condition_1(x:sympy.Rational):
	#Eq(x, 0)

	pre_cond = Equality(Symbol('x'), Integer(0))

	eval = pre_cond.subs( { 'x':x })

	if eval==True:
		assert eval!=False
		return True
	return False


